import { execFileSync } from 'node:child_process'
import { existsSync, readFileSync } from 'node:fs'
import { describe, expect, it } from 'vitest'

// docs/fork/AUDIT.md is generated by fork/scripts/generate-audit.py; this keeps it in step with the
// tree so a fork file is never added, removed or deleted without the table noticing.
const table = readFileSync('docs/fork/AUDIT.md', 'utf8')
const rows = [...table.matchAll(/^\| `([^`]+)` +\| [^|]+\| (\S+) +\|/gm)].map((match) => ({
  path: match[1],
  decision: match[2]
}))
const FORK_ROOTS = ['src/fork/', 'src/shared/fork-hooks/', 'fork/', 'docs/fork/']

describe('fork audit table', () => {
  it('lists each file once with a known decision', () => {
    expect(rows.length).toBeGreaterThan(200)
    expect(new Set(rows.map((row) => row.path)).size).toBe(rows.length)
    expect(
      rows.filter(
        (row) => !['keep', 'shrink', 'revert-to-upstream', 'delete'].includes(row.decision)
      )
    ).toEqual([])
  })

  it('kept and reverted files exist, deleted files are gone', () => {
    expect(rows.filter((row) => row.decision !== 'delete' && !existsSync(row.path))).toEqual([])
    expect(rows.filter((row) => row.decision === 'delete' && existsSync(row.path))).toEqual([])
  })

  it('covers every tracked fork-owned file', () => {
    const listed = new Set(rows.map((row) => row.path))
    const tracked = execFileSync('git', ['ls-files', '--', ...FORK_ROOTS, 'FORK-CHANGES.md'], {
      encoding: 'utf8'
    })
      .split('\n')
      .filter(Boolean)
    expect(tracked.length).toBeGreaterThan(100)
    expect(tracked.filter((path) => !listed.has(path))).toEqual([])
  })

  it('summary counts match the rows', () => {
    const counts = new Map<string, number>()
    for (const row of rows) {
      counts.set(row.decision, (counts.get(row.decision) ?? 0) + 1)
    }
    expect(table).toContain(`共 ${rows.length} 行`)
    for (const [decision, count] of counts) {
      expect(table).toContain(`${decision} ${count}`)
    }
  })
})
